// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }
    function testFuzz_property(uint256 first, uint256 second, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.assume(first <= 100 ether && second <= 100 ether);
        vm.assume(first + second >= first && first + second <= type(uint256).max / 2);
        vm.deal(actor, first + second);

        vm.prank(actor);
        c.Put{value: first}(0);
        vm.prank(actor);
        c.Put{value: second}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == first + second, "balance must accumulate deposits");
    }
}
